const AN_L=(x1,y1,x2,y2,col=AN_G,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const AN_D=(x1,y1,x2,y2,col=AN_G,w=2,d='7 6')=>AN_L(x1,y1,x2,y2,col,w,`stroke-dasharray="${d}"`);
const AN_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}/>`;
const AN_ar=(x1,y1,x2,y2,col='#18213A',w=4,dash='')=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return AN_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w,dash?`stroke-dasharray="${dash}"`:'')+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
/* a subscript that sits just below the line (tabs between attributes so wrapped lines never split the tag) */
const AN_sb=t=>`<tspan\tbaseline-shift="-0.2em"\tfont-size="72%">${t}</tspan>`;
const AN_pl=(pts,col,w=3,fill='none',fo=1)=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="${fill}" fill-opacity="${fo}" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`;
/* computed curves */
const AN_fn=(f,t0,t1,n=120)=>{const a=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;a.push([t,f(t)])}return a};
/* the dipole's polar pattern: radius R·F(θ) at angle θ from the vertical wire axis, both lobes */
const AN_dip=(cx,cy,R,F,col,w=3,fill='none',fo=.25)=>{const half=s=>AN_fn(t=>F(t),0,Math.PI,90).map(([t,v])=>[cx+s*R*v*Math.sin(t),cy-R*v*Math.cos(t)]);return AN_pl(half(1),col,w,fill,fo)+AN_pl(half(-1),col,w,fill,fo)};
/* field lines round a charge */
const AN_q=(x,y,col,op=1,dash='')=>{let s='';for(let i=0;i<8;i++){const a=i*Math.PI/4;s+=AN_L(x+22*Math.cos(a),y+22*Math.sin(a),x+44*Math.cos(a),y+44*Math.sin(a),col,3,`stroke-opacity="${op}"${dash?` stroke-dasharray="${dash}"`:''}`)}return s+`<circle cx="${x}" cy="${y}" r="15" fill="${col}" fill-opacity="${op}"/>`+AN_T(x,y+8,'+',{fs:24,fw:800,a:'middle',fill:'#FFFFFF'})};
/* wavefront arcs from a wire at (x,y), each kept within ±hh of y */
const AN_waves=(x,y,radii,hh,col,w=3)=>radii.map((r,i)=>{const a=Math.asin(Math.min(1,hh/r));return `<path d="M${(x+r*Math.cos(a)).toFixed(1)},${(y-r*Math.sin(a)).toFixed(1)} A${r},${r} 0 0,1 ${(x+r*Math.cos(a)).toFixed(1)},${(y+r*Math.sin(a)).toFixed(1)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-opacity="${1-i*.22}"/>`}).join('');
/* a current wave i(t) = I0 sin, x0..x1, centre yc, amplitude A, two cycles */
const AN_sine=(x0,x1,yc,A,col,w=4)=>AN_pl(AN_fn(t=>Math.sin(2*Math.PI*t),0,2,120).map(([t,v])=>[x0+(x1-x0)*t/2,yc-A*v]),col,w);
/* the sin θ field pattern drawn flat: θ from 0° to 180° on x0..x1, baseline yb, height H */
const AN_flat=(x0,x1,yb,H,f,col,w=4)=>AN_pl(AN_fn(t=>f(t),0,Math.PI,120).map(([t,v])=>[x0+(x1-x0)*t/Math.PI,yb-H*v]),col,w);

