function EXTRA(R,ICON){
 /* hook: a charge at steady speed, and a wire whose current changes */
 ICON.anStill=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${AN_box(0,0,380,170,{fill:'#FFFFFF',st:INK,sw:3,r:18})}
  ${AN_q(76,85,ORG)}${AN_ar(128,85,176,85,BLU,4)}
  ${AN_T(196,72,'steady speed:',{fs:24,fw:800,fill:INK})}${AN_T(196,110,'nothing leaves',{fs:22,fw:700,fill:AN_G})}</g>`;
 ICON.anShake=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${AN_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  ${AN_L(46,40,46,130,INK,7)}${AN_ar(68,110,68,46,GRN,3)}${AN_ar(68,64,68,124,GRN,3)}
  ${AN_waves(46,85,[70,105,140],58,BLU,3)}
  ${AN_T(206,72,'accelerating:',{fs:24,fw:800,fill:INK})}${AN_T(206,110,'a wave leaves',{fs:22,fw:700,fill:BLU})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.anRcDip=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${AN_D(210,0,210,290,AN_LG,2)}
  ${AN_dip(210,150,200,t=>Math.sin(t),BLU,4,BLU,.15)}<rect x="204" y="124" width="12" height="52" rx="3" fill="${INK}"/>
  ${AN_T(210,326,'E ∝ sin θ / r',{fs:28,fw:800,a:'middle',fill:BLU})}</g>`;
 ICON.anRcDG=(x,y)=>`<g transform="translate(${x-210} ${y-165})">
  <rect x="30" y="40" width="360" height="70" rx="6" fill="${BLU}"/><rect x="30" y="140" width="324" height="70" rx="6" fill="${GRN}"/><rect x="354" y="140" width="36" height="70" fill="${RED}" fill-opacity=".75"/>
  ${AN_T(50,88,'D = 1.5',{fs:30,fw:800,fill:'#FFFFFF'})}${AN_T(50,188,'G = 1.35',{fs:30,fw:800,fill:'#FFFFFF'})}
  ${AN_T(210,290,'G ≤ D',{fs:44,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.anRcHP=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${AN_L(20,280,400,280,AN_G,2)}
  ${AN_flat(20,400,280,240,t=>Math.sin(t)**2,GRN,5)}
  ${AN_D(20,160,400,160,ORG,3)}${AN_D(115,160,115,280,ORG,2)}${AN_D(305,160,305,280,ORG,2)}
  ${AN_L(115,230,305,230,ORG,4)}${AN_T(210,220,'90°',{fs:30,fw:800,a:'middle',fill:ORG})}
  ${AN_T(400,150,'−3 dB',{fs:26,fw:800,a:'end',fill:ORG})}${AN_T(210,318,'θ from 0° to 180°',{fs:22,fw:700,a:'middle',fill:AN_G})}</g>`;
}
